package connect

import "errors"

// ResultOf determines the winner of a Hex / Polygon board.
//
// The board is given as a list of rows. Each row is a string of cells
// containing 'X', 'O' or '.' (empty). Player X wins by connecting the
// left edge to the right edge; player O wins by connecting the top
// edge to the bottom edge.
func ResultOf(lines []string) (string, error) {
	if len(lines) == 0 {
		return "", nil
	}
	for _, l := range lines {
		for _, r := range l {
			if r != 'X' && r != 'O' && r != '.' {
				return "", errors.New("invalid board")
			}
		}
	}

	if connects(lines, 'X', 0, len(lines)-1) {
		return "X", nil
	}
	if connects(lines, 'O', 0, len(lines)-1) {
		return "O", nil
	}
	return "", nil
}
```

