package connect

import "errors"

// ResultOf computes the winner of a game of Hex (Polygon / CON-TAC-TIX).
//
// The board is a parallelogram of hexagonal cells given as rows of
// characters: 'X' and 'O' are stones and '.' is an empty cell.
// Player X plays from left to right, so X wins when a chain of X
// stones connects the left edge to the right edge. Player O plays from
// top to bottom, so O wins when a chain of O stones connects the top
// edge to the bottom edge. An empty string is returned when nobody has
// won.
func ResultOf(lines []string) (string, error) {
	if len(lines) == 0 {
		return "", nil
	}
	for _, line := range lines {
		for _, c := range line {
			if c != 'X' && c != 'O' && c != '.' {
				return "", errors.New("connect: board contains invalid cell")
			}
		}
	}

	if winner(lines, 'X', leftToRight) {
		return "X", nil
	}
	if winner(lines, 'O', topToBottom) {
		return "O", nil
	}
	return "", nil
}
```

