// neighbors of cell (r, c) in the parallelogram topology.
func neighbors(r, c, rows, cols int) [][2]int {
	return [][2]int{
		{r - 1, c - 1}, {r - 1, c},
		{r, c - 1}, {r, c + 1},
		{r + 1, c - 1}, {r + 1, c},
	}
}
```

